import axios from 'axios'
import { ElMessage } from 'element-plus'
import router from '@/router'

/**
 * 通用请求封装：不绑定任何具体业务接口，
 * 任意资源（文章、商品、用户等）均可复用 get/post/put/del。
 */

// 创建 axios 实例
const request = axios.create({
  // baseURL: process.env.VUE_APP_BASE_URL || 'http://localhost:8081',
  baseURL: process.env.VUE_APP_BASE_URL || 'https://recorders-ate-bye-eligible.trycloudflare.com',
  timeout: 10000
})

// 请求拦截器：统一携带登录凭证
request.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('coffer_token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }
    return config
  },
  (error) => Promise.reject(error)
)

// 响应拦截器：只处理 HTTP 层错误与登录态，业务结构交给调用方判断
request.interceptors.response.use(
  // 2xx：直接返回后端 body（如 {code,message,data}），由调用方解析
  (response) => response.data,
  // 非 2xx：统一提示错误；401 自动跳登录页
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('coffer_token')
      localStorage.removeItem('coffer_user')
      router.push('/login')
      ElMessage.error(error.response.data?.message || '登录已过期，请重新登录')
    } else {
      ElMessage.error(error.response?.data?.message || error.message || '网络异常，请稍后重试')
    }
    return Promise.reject(error)
  }
)

/**
 * GET 请求
 * @param {string} url 请求路径
 * @param {object} [params] 查询参数
 * @param {object} [config] 其它 axios 配置
 */
export const get = (url, params, config) =>
  request({ url, method: 'get', params, ...config })

/**
 * POST 请求
 * @param {string} url 请求路径
 * @param {object} [data] 请求体
 * @param {object} [config] 其它 axios 配置
 */
export const post = (url, data, config) =>
  request({ url, method: 'post', data, ...config })

/** PUT 请求（更新） */
export const put = (url, data, config) =>
  request({ url, method: 'put', data, ...config })

/** DELETE 请求（删除） */
export const del = (url, config) =>
  request({ url, method: 'delete', ...config })

export default request